import base64, json, subprocess, sys
PLAYER = "org.mpris.MediaPlayer2.Player"
def q(*args):
    try:
        r = subprocess.run(("busctl", "--user", "--json=short") + args, capture_output=True, text=True, timeout=3)
        return json.loads(r.stdout) if r.returncode == 0 and r.stdout.strip() else None
    except Exception:
        return None
def prop(name, iface, key):
    v = q("get-property", name, "/org/mpris/MediaPlayer2", iface, key)
    return v.get("data") if isinstance(v, dict) else None
def pick():
    names = [x["name"] for x in (q("list") or []) if str(x.get("name", "")).startswith("org.mpris.MediaPlayer2.")]
    status = {n: prop(n, PLAYER, "PlaybackStatus") for n in names}
    for want in ("Playing", "Paused"):
        for n in names:
            if status[n] == want:
                return n, want
    return None, None
name, status = pick()
if not name:
    print(json.dumps({"status": "Stopped"})); sys.exit()
m = prop(name, PLAYER, "Metadata") or {}
g = lambda k: (m.get(k) or {}).get("data")
artist = g("xesam:artist"); artist = ", ".join(artist) if isinstance(artist, list) else (artist or "")
art = g("mpris:artUrl") or ""
if art.startswith("file://"):
    try:
        raw = open(art[7:], "rb").read()
        art = "data:image/png;base64," + base64.b64encode(raw).decode() if len(raw) < 400000 else ""
    except OSError:
        art = ""
print(json.dumps({"status": status, "title": g("xesam:title") or "", "artist": artist,
                  "player": prop(name, "org.mpris.MediaPlayer2", "Identity") or name.split(".")[3],
                  "position": (prop(name, PLAYER, "Position") or 0) / 1e6,
                  "length": (g("mpris:length") or 0) / 1e6, "art": art}))
PYEOF

